import{_ as e,o as a,c as o,a1 as s}from"./chunks/framework.Ccs17H5l.js";const i="/eadkp/assets/Simulator_final.CXMsHKVv.png",m=JSON.parse('{"title":"Simulator","description":"","frontmatter":{},"headers":[],"relativePath":"guide/simulator.md","filePath":"guide/simulator.md"}'),r={name:"guide/simulator.md"};function l(n,t,u,c,p,d){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="simulator" tabindex="-1">Simulator <a class="header-anchor" href="#simulator" aria-label="Permalink to &quot;Simulator&quot;">​</a></h1><p>The template includes a simulator that lets you test your application on your computer without flashing it to the calculator.</p><h2 id="why-use-the-simulator" tabindex="-1">Why Use the Simulator <a class="header-anchor" href="#why-use-the-simulator" aria-label="Permalink to &quot;Why Use the Simulator&quot;">​</a></h2><p>This is especially valuable because the calculator&#39;s flash memory degrades with each write cycle, the less you write to it, the better.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>This is a <strong>simulator</strong>, not an <strong>emulator</strong>, it does not replicate the calculator&#39;s hardware. If your code directly accesses hardware, the simulator cannot handle it, and you will need to test on a physical device. In that case, consider providing a dummy/stub implementation of those features for use in the simulator.</p></div><h2 id="running-the-simulator" tabindex="-1">Running the Simulator <a class="header-anchor" href="#running-the-simulator" aria-label="Permalink to &quot;Running the Simulator&quot;">​</a></h2><p>Open a terminal (<strong>not</strong> an IDE-embedded terminal, a standalone one), navigate to your project folder (inside WSL if you&#39;re on Windows), and run:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">./docker.sh</span><span style="color:#CE9178;"> sim</span><span style="color:#CE9178;"> {threads}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Replace <code>{threads}</code> with the number of threads to allocate for compilation, more threads means faster builds.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This is the official Numworks simulator, downloaded from their GitHub repository and compiled locally. We cannot distribute a pre-compiled binary for licensing reasons.</p><p><strong>The first build may take a while, this is expected.</strong></p></div><p>Once running, a window representing a Numworks calculator will appear. You can interact with it just like a physical device.</p><p><img src="'+i+'" alt="illustration"></p><p><em>This illustration is deprecated; the template’s default UI no longer looks like this.</em></p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><p><strong>Black screen or freeze on startup:</strong> Your code likely has no way to exit its main loop. If nothing (e.g. a keypress) can break out of the loop, the simulator will not run it.</p></li><li><p><strong>Instant crash:</strong> Most likely caused by an instruction the simulator doesn&#39;t support, typically a hardware access attempt or use of an unsimulated feature.</p></li><li><p><strong>Window closes immediately:</strong> Your code probably has no main loop at all, so the program runs to completion and exits right away.</p></li></ul>',15)])])}const g=e(r,[["render",l]]);export{m as __pageData,g as default};
